package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.identidad.*;import cl.nexbyte.siger.institucional.identidad.CatalogoPlazos.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class PlazosRegistroTest {
 @TempDir Path temp;PlazosFixture f;DocumentosReqFixture x;
 @BeforeEach void setup()throws Exception{f=new PlazosFixture(temp);x=f.x;}
 @AfterEach void close()throws Exception{if(f!=null)f.close();}
 void denied(int status,Runnable action){assertEquals(status,assertThrows(FalloTecnico.class,action::run).status);}
 @Test void sinPoliticaHayHechosYNingunIncumplimientoNiReqOCasoFabricados(){long reqs=f.count("core_requirement"),cases=f.count("core_case");UUID com=f.manual(49*3600000L);var e=f.entrada("COM",com);assertEquals("SIN_POLITICA_APLICABLE",e.estado());assertNull(e.regla());assertEquals(49*3600000L,e.duracionCorridaMs());assertEquals(x.clock.instant().minusSeconds(49*3600L),e.efectiva());assertEquals(x.clock.instant(),e.registrada());assertTrue(e.mediciones().isEmpty());assertEquals(reqs,f.count("core_requirement"));assertEquals(cases,f.count("core_case"));assertEquals(0,f.count("temporal_measurement"));}
 @Test void politicaExpresaCorridaMideRegistroYReintentoNoCreaGestionNiOtraMedicion()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA")));UUID com=f.manual(49*3600000L),key=x.key();var e=f.entrada("COM",com);long acts=f.count("core_action"),reqs=f.count("core_requirement");var m=f.service.medir(x.f.a(x.f.profA),key,"COM",com,f.solicitud(e));assertEquals("FUERA_PLAZO",m.resultado());assertEquals(e.efectiva().plusSeconds(172800),m.vencimiento());assertEquals(49*3600000L,m.transcurridoMs());assertEquals(m,f.service.medir(x.f.a(x.f.profA),key,"COM",com,f.solicitud(e)));assertEquals(1,f.count("temporal_measurement"));assertEquals(1,f.count("temporal_measurement_command"));assertEquals(acts,f.count("core_action"));assertEquals(reqs,f.count("core_requirement"));assertTrue(f.entrada("COM",com).mediciones().getFirst().actual());
 }
 @Test void fuenteDeGestionGuardaAmbitoYFechasSinTomarElPrimerCasoDelReq()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_GESTION","CORRIDAS","ACTIVA")));long seq=x.gestion();var req=f.service.listar(x.f.a(x.f.profA),"REQ",x.req,0,25);var e=req.items().stream().filter(v->v.id().equals("REQ:"+seq)).findFirst().orElseThrow();assertEquals("GESTION_REQ",e.origen());assertEquals(x.clock.instant().minusSeconds(20),e.efectiva());assertEquals(20000,e.duracionCorridaMs());assertEquals("DENTRO_PLAZO",f.service.medir(x.f.a(x.f.profA),x.key(),"REQ",x.req,f.solicitud(e)).resultado());
  UUID cas=x.abrir();long rev=x.d.db.sql.queryForObject("SELECT revision FROM core_case WHERE id=?",Long.class,cas.toString());x.f.core.bitacora().registrarCaso(x.f.a(x.f.profA),x.key(),cas,new BitacoraGestion.Registrar("1.0",rev,x.clock.instant().minusSeconds(30),"Gestión real de Caso sintético",null,null));var ce=f.entrada("CASO",cas);assertEquals("GESTION_CASO",ce.origen());assertEquals(30000,ce.duracionCorridaMs());var source=x.d.db.sql.queryForMap("SELECT * FROM temporal_registration_source WHERE id=?",ce.id());assertEquals("AREA_A",source.get("area_id"));assertEquals("UPR",source.get("unit_code"));assertEquals(1,f.service.listar(x.f.a(x.f.profA),"CASO",cas,0,25).total());
 }
 @Test void habilesNecesitaCalendarioFirmadoYNoPresuponeFeriadosOUnOffset()throws Exception{
  f.instalar(List.of(f.calendario()),List.of(f.politica("REGISTRO_ATENCION","HABILES","ACTIVA")));UUID com=f.manual(49*3600000L);var e=f.entrada("COM",com);var m=f.service.medir(x.f.a(x.f.profA),x.key(),"COM",com,f.solicitud(e));assertEquals("DENTRO_PLAZO",m.resultado());assertTrue(m.transcurridoMs()<49*3600000L);assertNotNull(e.regla().huellaCalendario());assertEquals("TEST_CAL",e.regla().calendario());
 }
 @Test void suspenderPoliticaConservaMedicionHistoricaYNoHabilitaOtroCalculo()throws Exception{
  var p=f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA");f.instalar(List.of(),List.of(p));UUID com=f.manual(49*3600000L),key=x.key();var e=f.entrada("COM",com);var first=f.service.medir(x.f.a(x.f.profA),key,"COM",com,f.solicitud(e));f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","SUSPENDIDA")));var after=f.entrada("COM",com);assertEquals("SIN_POLITICA_APLICABLE",after.estado());assertFalse(after.mediciones().getFirst().actual());assertEquals(first.id(),after.mediciones().getFirst().id());denied(409,()->f.service.medir(x.f.a(x.f.profA),x.key(),"COM",com,f.solicitud(e)));assertFalse(f.service.medir(x.f.a(x.f.profA),key,"COM",com,f.solicitud(e)).actual());assertEquals(1,f.count("temporal_measurement"));assertEquals(1,f.count("temporal_policy_version"));
 }
 @Test void mismaVersionNoCambiaDeSignificadoNiDejaUnRegistroDeAutoridadParcial()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA")));long rev=x.d.db.sql.queryForObject("SELECT revision FROM authority_registry WHERE id=1",Long.class);var bad=f.registro(List.of(f.calendario()),List.of(f.politica("REGISTRO_ATENCION","HABILES","ACTIVA")));denied(409,()->{try{x.f.importar(bad);}catch(RuntimeException e){throw e;}catch(Exception e){throw new RuntimeException(e);}});assertEquals(rev,x.d.db.sql.queryForObject("SELECT revision FROM authority_registry WHERE id=1",Long.class));assertEquals(0,f.count("temporal_calendar_version"));assertEquals(1,f.count("temporal_policy_version"));
 }
 @Test void otraAreaTiYOtroReqNoLeenCuentanNiMidenFuentesAjena()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_GESTION","CORRIDAS","ACTIVA")));long seq=x.gestion();var e=f.service.listar(x.f.a(x.f.profA),"REQ",x.req,0,25).items().stream().filter(v->v.id().equals("REQ:"+seq)).findFirst().orElseThrow();for(String actor:List.of(x.f.profB,x.f.headB,x.f.ti,x.f.dist)){denied(404,()->f.service.listar(x.f.a(actor),"REQ",x.req,0,25));denied(404,()->f.service.medir(x.f.a(actor),x.key(),"REQ",x.req,f.solicitud(e)));}UUID other=x.nuevoReq();denied(404,()->f.service.medir(x.f.a(x.f.profA),x.key(),"REQ",other,f.solicitud(e)));assertEquals(0,f.count("temporal_measurement"));assertEquals(1,f.service.listar(x.f.a(x.f.profA),"REQ",x.req,1,1).items().size());
 }
 @Test void dosCalculosConcurrentesConservanLaMismaMedicionSinDuplicarHechos()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA")));UUID com=f.manual(49*3600000L);var e=f.entrada("COM",com);var go=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<PlazosRegistro.Medicion> op=()->{go.await();return f.service.medir(x.f.a(x.f.profA),x.key(),"COM",com,f.solicitud(e));};var a=pool.submit(op);var b=pool.submit(op);go.countDown();assertEquals(a.get(8,TimeUnit.SECONDS).id(),b.get(8,TimeUnit.SECONDS).id());}assertEquals(1,f.count("temporal_measurement"));assertEquals(2,f.count("temporal_measurement_command"));
 }
 @Test void falloDelComandoRevierteMedicionYAuditoriaPeroConservaFuente()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA")));UUID com=f.manual(49*3600000L);var e=f.entrada("COM",com);long audits=x.d.db.sql.queryForObject("SELECT COUNT(*) FROM matter_access_event WHERE action_code='PLAZO_MEDICION_CONFIRMADA'",Long.class);x.d.ddl(sql->sql.execute("ALTER TABLE temporal_measurement_command ADD CONSTRAINT tiempo_rollback CHECK(resource_kind='REQ')"));try{var ex=assertThrows(org.springframework.dao.DataAccessException.class,()->f.service.medir(x.f.a(x.f.profA),x.key(),"COM",com,f.solicitud(e)));assertTrue(org.springframework.core.NestedExceptionUtils.getMostSpecificCause(ex).getMessage().toLowerCase(Locale.ROOT).contains("tiempo_rollback"));}finally{x.d.ddl(sql->sql.execute("ALTER TABLE temporal_measurement_command DROP "+(System.getProperty("siger.test.autoridad.mysql")==null?"CONSTRAINT":"CHECK")+" tiempo_rollback"));}assertEquals(0,f.count("temporal_measurement"));assertEquals(0,f.count("temporal_measurement_command"));assertEquals(audits,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM matter_access_event WHERE action_code='PLAZO_MEDICION_CONFIRMADA'",Long.class));assertEquals(e,f.entrada("COM",com));
 }
 @Test void fuenteOMedicionAlteradaFallaCerradaSinRecalcularUnaHistoriaFalsa()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA")));UUID com=f.manual(49*3600000L);var e=f.entrada("COM",com);var m=f.service.medir(x.f.a(x.f.profA),x.key(),"COM",com,f.solicitud(e));x.d.db.sql.update("UPDATE temporal_measurement SET elapsed_ms=0 WHERE id=?",m.id().toString());denied(409,()->f.entrada("COM",com));x.d.db.sql.update("UPDATE temporal_registration_source SET effective_ms=effective_ms+1 WHERE id=?",e.id());denied(409,()->f.service.medir(x.f.a(x.f.profA),x.key(),"COM",com,f.solicitud(e)));assertEquals(1,f.count("temporal_measurement"));
 }
 @Test void fechaServidorSeUsaUnaVezParaElSelloAunqueElRelojAvance()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA")));UUID com=f.manual(49*3600000L);var e=f.entrada("COM",com);var ticks=new java.util.concurrent.atomic.AtomicLong();Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return Instant.ofEpochMilli(millis());}public long millis(){return x.clock.millis()+ticks.getAndIncrement();}};var service=new PlazosRegistro(x.d.db,x.f.core,x.f.cat,x.f.f.autoridades,clock);var m=service.medir(x.f.a(x.f.profA),x.key(),"COM",com,f.solicitud(e));assertEquals(m,f.entrada("COM",com).mediciones().getFirst());
 }
 @Test void expiracionDuranteElCalculoRevierteElResultadoAlRevalidar()throws Exception{
  f.instalar(List.of(),List.of(f.politica("REGISTRO_ATENCION","CORRIDAS","ACTIVA")));UUID com=f.manual(49*3600000L);var e=f.entrada("COM",com);var actor=x.f.a(x.f.profA);Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return Instant.ofEpochMilli(millis());}public long millis(){x.clock.avanzar(1801);return x.clock.millis();}};var service=new PlazosRegistro(x.d.db,x.f.core,x.f.cat,x.f.f.autoridades,clock);denied(403,()->service.medir(actor,x.key(),"COM",com,f.solicitud(e)));assertEquals(0,f.count("temporal_measurement"));assertEquals(0,f.count("temporal_measurement_command"));
 }
}
